using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using Newtonsoft.Json.Linq;using Unity.Entities;namespace Game.Runtime{internal sealed partial class AutonomousWorld{
 internal JObject BindActualBuildingRequestMetadata(string path,string expected,string sourceRepo,string dataRepo,bool publishImmediately=true){
 if(StartingPipeline==null||StartingPipeline.ConfiguredRequestMetadataKnown||ActualUnitMetadata==null)throw new InvalidOperationException("Bind real configured metadata once after canonical source initialization");
 var raw=ReadConfigured(path,expected,4*1024*1024);var root=JObject.Parse(System.Text.Encoding.UTF8.GetString(raw));
 if((int?)root["schema_version"]!=(MetadataCompatibility?.ProjectionSchemaVersion??1)||(string)root["kind"]!=(MetadataCompatibility?.FactoryDomainQualified==true?MetadataCompatibility.ProjectionKind("NativeQualifiedConfiguredBuildingMetadata"):"CurrentSourceBuildingRequestMetadataSupplement"))throw new InvalidDataException("Unsupported configured metadata scope");
 var refs=(JObject)root["reference"];var referenceBytes=ReadConfigured((string)refs["path"],(string)refs["sha256"],4*1024*1024);var reference=JObject.Parse(System.Text.Encoding.UTF8.GetString(referenceBytes));
 if(MetadataCompatibility!=null)MetadataCompatibility.RequireConfigured(reference,root,Setup.SetupHash,Setup.Seed);
 if(MetadataCompatibility==null&&((uint)reference["setup_hash"]!=Setup.SetupHash||(int)reference["seed"]!=Setup.Seed))throw new NotSupportedException("Configured provider witness must match actual compiled setup/seed");
 var pins=new Dictionary<string,string>(StringComparer.Ordinal);
 void Admit(string recorded,string digest,bool code){int i=recorded.IndexOf("/Assets/",StringComparison.Ordinal);string relative=recorded.StartsWith("Assets/",StringComparison.Ordinal)?recorded:(i>=0?recorded.Substring(i+1):throw new InvalidDataException("Expected repository asset/source pin: "+recorded));if(relative.Split('/').Any(x=>x==".."||x=="."||x==""))throw new InvalidDataException("Canonical metadata repository path required");string actual=Path.GetFullPath(Path.Combine(code?sourceRepo:ConfiguredHistoricalRoot(dataRepo),relative));VerifyConfigured(actual,digest);if(pins.TryGetValue(actual,out var previous)&&previous!=digest)throw new InvalidDataException("Conflicting metadata epoch");pins[actual]=digest;}
 foreach(var pin in ((JObject)root["source_pins"]).Properties()){if(Path.GetFullPath(pin.Name)==Path.GetFullPath((string)refs["path"])){if((string)pin.Value!=(string)refs["sha256"])throw new InvalidDataException("Conflicting selected-reference epoch");pins[Path.GetFullPath(pin.Name)]=(string)pin.Value;}else Admit(pin.Name,(string)pin.Value,pin.Name.EndsWith(".cs",StringComparison.Ordinal));}
 var sourcePins=(JObject)reference["source_pins"];foreach(var pin in sourcePins.Properties()){bool prefab=pin.Name.EndsWith(".prefab",StringComparison.Ordinal)||pin.Name.EndsWith(".prefab.meta",StringComparison.Ordinal);bool selector=pin.Name.EndsWith("/Runtime/Skirmish/SkirmishProductionCatalog.cs",StringComparison.Ordinal)||pin.Name.EndsWith("/Systems/BuildingDefinitionPrefabSystemHelper.cs",StringComparison.Ordinal);if(prefab||selector)Admit(pin.Name,(string)pin.Value,selector);}
 var rows=((JArray)root["rows"]).Cast<JObject>().ToArray();if(rows.Length!=SourceDefinitions.Definitions.Count)throw new InvalidDataException("Complete existing definition metadata required");var byKey=SourceDefinitions.Definitions.ToDictionary(d=>d.Prefab.name,StringComparer.Ordinal);var entries=new Dictionary<SourceUnitPrefab,BuildingUiCommandSystemHelper.ConfiguredSpawnableEntry>();var mapped=new Dictionary<JObject,SourceUnitPrefab>();var selected=((JArray)reference["definitions"]).Cast<JObject>().ToDictionary(r=>(string)r["key"],StringComparer.Ordinal);
 foreach(var row in rows){string key=(string)row["key"];if(!byKey.TryGetValue(key,out var definition)||!selected.TryGetValue(key,out var native)||!JToken.DeepEquals(native["prefab"],row["prefab"])||!SourceDefinitions.AssetIdentities.TryGetValue(key,out var identity)||!JToken.DeepEquals(identity,row["prefab"])||(string)row["display_name"]!=definition.DisplayName||row["can_request"].Type!=JTokenType.Boolean)throw new InvalidDataException("Exact native selected prefab/definition metadata identity required: "+key);mapped.Add(row,definition.Prefab);entries.Add(definition.Prefab,new BuildingUiCommandSystemHelper.ConfiguredSpawnableEntry(definition.DisplayName,definition.Description,definition.Prefab,(bool)row["can_request"],Math.Max(0,definition.CreditsCost)));}
 var baselineRows=rows.Where(r=>r["construction_catalog_index"].Type!=JTokenType.Null).OrderBy(r=>(int)r["construction_catalog_index"]).ToArray();for(int i=0;i<baselineRows.Length;i++)if((int)baselineRows[i]["construction_catalog_index"]!=i)throw new InvalidDataException("Complete baseline configured list required");var sceneRows=rows.Where(r=>r["scene_catalog_index"].Type!=JTokenType.Null).OrderBy(r=>(int)r["scene_catalog_index"]).ToArray();
 // Relevant scene names have an actual selected-prefab witness in the R6 export. Every current selector/factory and prefab dependency is checked above; unrelated scene UI inventory is not reconstructed.
 var order=SourceConfiguredBuildingSelection.Select(Setup,new SourceBuildingProvider(baselineRows.Select(r=>mapped[r]).ToArray()),new SourceBuildingProvider(sceneRows.Select(r=>mapped[r]).ToArray()),ActualUnitMetadata.Ordered.ToDictionary(r=>r.Prefab.name,r=>r.Prefab,StringComparer.Ordinal));
 foreach(var pin in pins)VerifyConfigured(pin.Key,pin.Value);VerifyConfigured(path,expected);VerifyConfigured((string)refs["path"],(string)refs["sha256"]);
 MetadataCompatibility?.VerifyUnchanged();StartingPipeline.BindConfiguredRequestMetadata(order,entries,publishImmediately);return new JObject{["kind"]="SourceConfiguredBuildingFacts",["count"]=order.Count,["order"]=new JArray(order.Select(p=>p.name)),["dependency_pins"]=JObject.FromObject(pins),["scope"]="Current source native configured-provider selection over existing R6 selected-prefab witness and current serialized authoring supplement; no raw scene UI inventory/native readiness claim"};
 }
 static string ConfiguredHistoricalRoot(string actual){if(!ConfiguredMapping)return actual;string original=Environment.GetEnvironmentVariable("WARLINE_PINNED_ROOT_ORIGINAL"),local=Environment.GetEnvironmentVariable("WARLINE_PINNED_ROOT_LOCAL");if(string.IsNullOrEmpty(original)||string.IsNullOrEmpty(local)||!Path.IsPathRooted(original)||!Path.IsPathRooted(local)||Path.GetFullPath(original)!=original||Path.GetFullPath(local)!=local)throw new InvalidDataException("Exact absolute relocation roots required");return actual==local?original:actual;}
 static bool ConfiguredMapping=>!string.IsNullOrEmpty(Environment.GetEnvironmentVariable("WARLINE_PINNED_ROOT_ORIGINAL"))||!string.IsNullOrEmpty(Environment.GetEnvironmentVariable("WARLINE_PINNED_ROOT_LOCAL"));
 static byte[] ReadConfigured(string path,string sha,long max){if(ConfiguredMapping)return PinnedFile(path,sha,max);var value=File.ReadAllBytes(path);if(HashConfigured(value)!=sha)throw new InvalidDataException("Configured metadata changed: "+path);return value;}
 static void VerifyConfigured(string path,string sha){if(ConfiguredMapping){VerifyPinnedFile(path,sha,256L*1024*1024);return;}if(HashConfigured(File.ReadAllBytes(path))!=sha)throw new InvalidDataException("Configured metadata changed: "+path);}
 private static string HashConfigured(byte[] value){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(value)).Replace("-","").ToLowerInvariant();}
}}
